    if(useVariants){if(!state.parsed.variants)throw new Error("Chargez d’abord l’export des versions de routes HASTUS.");const variant=timingPointsFromVariants(state.parsed.variants,gtfs.rows);timingIds=variant.timing;timingRows=times.rows.filter(row=>timingIds.has(normalize(row.stop_id)));state.variantStopIds=variant.all;state.endpointStopIds=variant.endpoints;state.timingSourceStats={rows:state.parsed.variants.rows.length,timing:timingIds.size,allStops:variant.all.size,endpoints:variant.endpoints.size,unmatched:variant.unmatched.size};}
    state.timingPointIds=new Set(timingIds);
