      dialog.querySelector('iframe').srcdoc=html;dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dialog.remove();$('open-network-module').focus();});document.body.append(dialog);dialog.showModal();
