async function cschedLogoDataUrl(){try{const response=await fetch(new URL("assets/csched-logo.svg",location.href));if(!response.ok)throw new Error("Logo CSched indisponible");const blob=await response.blob();return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}catch(error){console.warn(error);return "";}}
